    local pscroll=newI("ScrollingFrame",{Active=true,Position=UDim2.fromOffset(0,HEADP),Size=UDim2.new(1,0,1,-HEADP),BackgroundTransparency=1,BorderSizePixel=0,ScrollBarThickness=2,CanvasSize=UDim2.new(),AutomaticCanvasSize=Enum.AutomaticSize.Y,ScrollingDirection=Enum.ScrollingDirection.Y,ZIndex=3},body) pscroll.ScrollBarImageColor3=Theme.Accent
    local plist=newI("UIListLayout",{Padding=UDim.new(0,8),SortOrder=Enum.SortOrder.LayoutOrder},pscroll) newI("UIPadding",{PaddingTop=UDim.new(0,10),PaddingBottom=UDim.new(0,12),PaddingLeft=UDim.new(0,10),PaddingRight=UDim.new(0,10)},pscroll)
    local minH=110 local function fit() if destroyed then return end local maxH=math.max(minH,gui.AbsoluteSize.Y*0.7) local want=HEADP+22+plist.AbsoluteContentSize.Y local sz=UDim2.fromOffset(W+GRIP_W,math.clamp(math.floor(want),minH,maxH)) holder.Size=sz end plist:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(fit)
    local function goTo(open) prog=open and 1 or 0 play(holder,{Position=pos(prog)},0.45,Enum.EasingStyle.Quint) play(psh,{ImageTransparency=open and 0.5 or 1},0.4) end
    cb.MouseButton1Click:Connect(function() goTo(false) end)
    do local dragging=false local sPos=nil local sProg=nil grip.InputBegan:Connect(function(input) if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then dragging=true sPos=input.Position sProg=prog local conn; local ended=false conn=UIS.InputChanged:Connect(function(i) if not dragging then return end if i.UserInputType==Enum.UserInputType.MouseMovement or i.UserInputType==Enum.UserInputType.Touch then local dx=i.Position.X-sPos.X prog=math.clamp(sProg - dx/(W+M),0,1) holder.Position=pos(prog) psh.ImageTransparency=1-0.5*prog end end) input.Changed:Connect(function() if (input.UserInputState==Enum.UserInputState.End or input.UserInputState==Enum.UserInputState.Cancel) and not ended then ended=true dragging=false if conn then conn:Disconnect() end if math.abs(input.Position.X-sPos.X)<4 then goTo(prog<0.5) else goTo(prog>0.5) end end end) end end) end
    local cardCache={}
    local function createCard(m,cash,txtCash)
        local rarity=m:GetAttribute("Rarity") or "Unknown"
        local zone=getAnimalZone(m)
        local weight=m:GetAttribute("WeightKg") or m:GetAttribute("Weight") or 0
        local color=getRarityColor(rarity)
        local card=newI("Frame",{Size=UDim2.new(1,0,0,92),BackgroundColor3=Theme.ElementBackground,BorderSizePixel=0,LayoutOrder=-cash,ZIndex=4},nil) corner(card,10) stroke(card,Theme.Outline,1,0.22)
        local bar=newI("Frame",{Size=UDim2.new(0,4,1,0),Position=UDim2.new(0,0,0,0),BackgroundColor3=color,BorderSizePixel=0,ZIndex=5},card) corner(bar,10)
        local n1=txt(card,{Text=m.Name:upper(),Position=UDim2.fromOffset(16,8),Size=UDim2.new(0.52,-16,0,15),Font=Enum.Font.GothamBold,TextSize=12,ZIndex=5})
        local c1=txt(card,{Text=txtCash,Position=UDim2.new(0.52,0,0,8),Size=UDim2.new(0.48,-12,0,15),Font=Enum.Font.GothamBold,TextSize=11,TextColor3=Color3.fromRGB(80,255,160),TextXAlignment=Enum.TextXAlignment.Right,ZIndex=5})
        local badge=newI("Frame",{Position=UDim2.fromOffset(16,28),Size=UDim2.fromOffset(56,16),BackgroundColor3=color,BackgroundTransparency=0.82,BorderSizePixel=0,ZIndex=5},card) corner(badge,5)
        local r1=txt(badge,{Text=string.upper(rarity),Size=UDim2.fromScale(1,1),Font=Enum.Font.GothamBold,TextSize=8,TextColor3=color,TextXAlignment=Enum.TextXAlignment.Center,TextYAlignment=Enum.TextYAlignment.Center,ZIndex=6})
        local zoneLbl=txt(card,{Text=zone,Position=UDim2.fromOffset(78,28),Size=UDim2.new(0,90,0,16),Font=Enum.Font.Gotham,TextSize=10,TextColor3=Theme.TextSecondary,ZIndex=5})
        local w1=txt(card,{Text=tostring(weight).." KG",Position=UDim2.new(0,0,0,28),Size=UDim2.new(1,-12,0,16),Font=Enum.Font.GothamMedium,TextSize=10,TextColor3=Theme.TextSecondary,TextXAlignment=Enum.TextXAlignment.Right,ZIndex=5})
        local btn=newI("TextButton",{Size=UDim2.new(1,-16,0,28),Position=UDim2.new(0,8,0,52),BackgroundColor3=Theme.Accent,Text="STEAL",Font=Enum.Font.GothamBold,TextSize=11,TextColor3=Color3.new(1,1,1),AutoButtonColor=false,BorderSizePixel=0,ZIndex=5},card) corner(btn,8) stroke(btn,Theme.Accent,1,0.35)
        btn.MouseEnter:Connect(function() play(btn,{BackgroundColor3=Theme.Accent:Lerp(Color3.new(1,1,1),0.15)},0.15) end)
        btn.MouseLeave:Connect(function() play(btn,{BackgroundColor3=Theme.Accent},0.15) end)
        btn.MouseButton1Click:Connect(function() btn.Text=trackerMode=="Blatant" and "STEALING..." or "WALKING..." task.spawn(function() pcall(function() if trackerMode=="Blatant" then instantSteal(m) else legitStealTracker(m) end end) task.wait(0.3) if btn.Parent then btn.Text="STEAL" end end) end)
        return card,{cash=c1,rarity=r1,name=n1,weight=w1,bar=bar,frame=card,zone=zoneLbl,badge=badge,badgeBg=badge}
    end
    local function refresh() local folder=workspace:FindFirstChild("AnimalPickups") if not folder then sl.Text="0 animals" for _,d in pairs(cardCache) do if d.frame then d.frame:Destroy() end end table.clear(cardCache) fit() return end local list={} for _,m in ipairs(folder:GetChildren()) do if m:IsA("Model") then local ct=getCashPerSecond(m) local cv=parseCash(ct) if cv==0 then local at=m:GetAttribute("CashPerSecond") or m:GetAttribute("CPS") if typeof(at)=="number" then cv=at ct="$"..tostring(at).."/s" elseif typeof(at)=="string" then cv=parseCash(at) end end table.insert(list,{model=m,cash=cv,txt=ct}) end end table.sort(list,function(a,b) return a.cash>b.cash end) sl.Text=tostring(#list).." animals • "..trackerMode local seen={} for _,info in ipairs(list) do local m=info.model seen[m]=true local data=cardCache[m] if not data then local f,d=createCard(m,info.cash,info.txt) f.Parent=pscroll d.frame=f cardCache[m]=d else data.cash.Text=info.txt data.frame.LayoutOrder=-info.cash local rar=m:GetAttribute("Rarity") or "Unknown" local col=getRarityColor(rar) data.rarity.Text=string.upper(rar) data.rarity.TextColor3=col data.badgeBg.BackgroundColor3=col data.bar.BackgroundColor3=col data.name.Text=m.Name:upper() local w=m:GetAttribute("WeightKg") or m:GetAttribute("Weight") or 0 data.weight.Text=tostring(w).." KG" data.zone.Text=getAnimalZone(m) end end for m,d in pairs(cardCache) do if not seen[m] or not m.Parent then if d.frame then d.frame:Destroy() end cardCache[m]=nil end end fit() end
    task.spawn(function() while not destroyed do pcall(refresh) task.wait(0.6) end end)
end
plr.CharacterAdded:Connect(function(char) task.wait(0.5) local hum=char:WaitForChild("Humanoid",15) if hum then local realSpeed=hum.WalkSpeed sliderSpeed=realSpeed hum:SetAttribute("BaseSpeed",realSpeed) if walkSliderRef then walkSliderRef:Set(realSpeed) end end task.wait(0.5) if noRagdollOn then enableNoRagdoll() end if fastBreakOn then setFastBreakAttribute(true) end if clearOnRespawn then clearAllEsp() clearAllEggEsp() end if espEnabled then task.wait(0.5) refreshAllEsp() end if eggEspEnabled then task.wait(0.5) refreshEggEsp() end end)
plr.CharacterAdded:Connect(function(char) if pendingTeleportZone then local zoneName=pendingTeleportZone local hrp=char:WaitForChild("HumanoidRootPart",15) if hrp then task.wait(0.2) local pos=getZoneTeleportPos(zoneName) if pos then hrp.CFrame=CFrame.new(pos) task.wait(0.15) hrp.CFrame=CFrame.new(pos) end end pendingTeleportZone=nil end end)
RunService.Heartbeat:Connect(function() local hum=plr.Character and plr.Character:FindFirstChildOfClass("Humanoid") if hum then if math.abs(hum.WalkSpeed-sliderSpeed)>0.1 then hum.WalkSpeed=sliderSpeed end end end)
